window.INTERVIEW_EXECUTION["swift-24"] = {"timeBudget": {"navigation": 4, "solution": 9, "coding": 26, "verification": 6}, "navigation": {"say": "Before I code I want to pin down what counts as a window, because that decides three of the four parts.", "questions": ["Is a window always non-empty, so an all-negative series still has an answer?", "Is endIndex inclusive, and how should I break a tie between two windows with the same total?", "On the circular cycle, may a window wrap more than once, or is it bounded by the series length?"], "assumptions": ["A window is contiguous, non-empty, and endIndex is inclusive.", "Ties resolve to the earliest start and then the shortest window.", "The empty series is the only input that is a typed failure; every other series has an answer."], "edgeCases": ["every interval negative, where the answer is the least bad single interval and never zero", "a series that opens with a negative interval, where the window must not be anchored at index zero", "the circular cycle whose best window wraps, and the all-negative cycle where wrapping is illegal", "a one-interval series, which is a legal window in every part"], "restate": "Find the worst contiguous drift window in a signed series, report its bounds, extend it to a wrapping duty cycle, and score the largest deviation in either direction."}, "solution": {"pitch": "One linear scan whose state is the best window ending exactly at the current interval. Once the state is defined that way, every part is that scan run once or twice with a different comparison.", "dataStructures": ["No table is stored: the scan carries a running total, the index the run started at, and the best window seen so far.", "DriftWindow is the reconstruction, so the bounds are snapshotted the instant the best improves rather than recovered afterwards."], "types": ["DriftWindow is a small Equatable struct so a whole result compares in one expectation instead of three.", "DriftError makes the empty series a typed failure, which keeps a force unwrap or an out-of-range subscript out of the scan entirely."], "composition": "One private extremeWindow(deltas, maximising:) is the spine. worstWindow calls it once, worstTotal reads that window's total, and Parts 3 and 4 each call it twice, once in each direction.", "tradeoff": "Keeping the start index costs two extra variables and buys reconstruction. Rolling scalars with no indices would be marginally leaner and could not answer Part 2 at all, so the richer version is the one to write first.", "trap": "Seeding the running total or the answer at zero. It passes every mixed fixture and fails only when no interval is positive, which is precisely the case a drifting sensor produces."}, "coding": {"order": ["Write extremeWindow first with the maximising flag, even though Part 1 only needs one direction. It is the same amount of code and it is what Parts 3 and 4 will call.", "Implement worstWindow as the guard plus one call, then worstTotal as a projection of it.", "Add worstCircularTotal as interior best, then total minus the smallest window, with the all-negative guard stated out loud.", "Finish with largestDriftMagnitude as the larger of the largest window and the negated smallest."], "commentary": ["My state is the best window ending exactly here, which is why there is no inner loop.", "The run restarts when it stops helping, and that is the only moment the start index moves.", "I record the best only on a strict improvement, which is what gives the earliest start on a tie.", "A wrapping window is the complement of an interior one, so the smallest window names the best wrap without a second algorithm."], "checkIn": "After Part 2, say: the window is the primitive and the total is a projection of it, so there is one scan in this file. Does that match what you want to see?"}, "verification": {"walkthroughs": ["Walk the series -2, 3, -1, 4, -6, 2 by hand: the run restarts at index 1, peaks at 6 across indices 1 to 3, and never beats 6 afterwards.", "Walk 5, -3, 5 on the cycle: the interior best is 7, the smallest window is -3, and 7 minus -3 gives the wrapping answer 10.", "Walk -4, -7, 1 for magnitude: the largest window is 1, the smallest is -11, so the score is 11.", "Walk -8, -3, -5 through every part and confirm nothing anywhere reports zero."], "tests": "Run swift test --filter Problem24SensorDriftWindowDetectorTests and read the four suites in part order; the tie fixtures and the all-negative fixtures are the ones that actually discriminate.", "complexity": "Every part is O(n) time and O(1) extra space, with Parts 3 and 4 making two passes. The naive alternative enumerates every window at O(n squared), which is what the state definition removes.", "moreTime": "The same shape extends to a multiplicative fold, where the sign of an interval swaps the roles of the largest and smallest run and both must be carried and updated from the previous pair at once. A minimum-length constraint is a genuinely different algorithm behind the same story: prefix sums plus a running minimum over an offset window."}, "code": "/// One contiguous stretch of sampling intervals, with the cumulative drift it\n/// accumulated. `endIndex` is inclusive so a single interval is a legal window.\npublic struct DriftWindow: Equatable, Sendable {\n    public let startIndex: Int\n    public let endIndex: Int\n    public let total: Int\n\n    public init(startIndex: Int, endIndex: Int, total: Int) {\n        self.startIndex = startIndex\n        self.endIndex = endIndex\n        self.total = total\n    }\n}\n\npublic enum DriftError: Error, Equatable, Sendable {\n    case emptySeries\n    case notImplemented\n}\n\npublic struct DriftDetector: Sendable {\n    public init() {}\n\n    // MARK: Shared machinery\n\n    /// The one scan every part is built on: the extreme contiguous window of\n    /// `deltas`, either the largest total (`maximising`) or the smallest.\n    ///\n    /// The state that makes this linear is \"the extreme window that ends exactly\n    /// at `index`\". Extending is worth it only when the run so far helps, which\n    /// is the sole difference between the two directions, so one function serves\n    /// both rather than two near-identical copies drifting apart.\n    ///\n    /// Ties resolve to the earliest start and then the shortest window. Both fall\n    /// out of the same two rules: keep the running start when the run so far is\n    /// neutral, and replace the recorded best only on a strict improvement.\n    ///\n    /// The caller guarantees `deltas` is non-empty; that check belongs to the\n    /// public methods, which own the typed failure.\n    private func extremeWindow(_ deltas: [Int], maximising: Bool) -> DriftWindow {\n        var runningTotal = deltas[0]\n        var runningStart = 0\n        var best = DriftWindow(startIndex: 0, endIndex: 0, total: deltas[0])\n\n        for index in 1..<deltas.count {\n            let delta = deltas[index]\n            let runHelps = maximising ? runningTotal >= 0 : runningTotal <= 0\n            if runHelps {\n                runningTotal += delta\n            } else {\n                runningTotal = delta\n                runningStart = index\n            }\n\n            let improved = maximising ? runningTotal > best.total : runningTotal < best.total\n            if improved {\n                best = DriftWindow(startIndex: runningStart, endIndex: index, total: runningTotal)\n            }\n        }\n\n        return best\n    }\n\n    // MARK: Part 1 - Worst contiguous drift total\n\n    /// The worst window's total. The window itself is the primitive, so this is\n    /// a projection of Part 2 rather than a second scan with the bookkeeping\n    /// stripped out.\n    public func worstTotal(deltas: [Int]) throws(DriftError) -> Int {\n        try worstWindow(deltas: deltas).total\n    }\n\n    // MARK: Part 2 - Report the window bounds\n\n    public func worstWindow(deltas: [Int]) throws(DriftError) -> DriftWindow {\n        guard !deltas.isEmpty else { throw .emptySeries }\n        return extremeWindow(deltas, maximising: true)\n    }\n\n    // MARK: Part 3 - Circular duty cycles\n\n    /// On a circular cycle the worst window either stays inside the series or\n    /// wraps. A wrapping window is exactly the complement of a non-wrapping one,\n    /// so the smallest interior window names the best wrap without a second\n    /// algorithm.\n    ///\n    /// The guard matters: when every delta is negative the complement of the\n    /// smallest window is the empty window, which is not a window at all. The\n    /// non-wrapping answer already is the whole answer there.\n    public func worstCircularTotal(deltas: [Int]) throws(DriftError) -> Int {\n        guard !deltas.isEmpty else { throw .emptySeries }\n        let interior = extremeWindow(deltas, maximising: true).total\n        guard interior >= 0 else { return interior }\n        let smallest = extremeWindow(deltas, maximising: false).total\n        return max(interior, deltas.reduce(0, +) - smallest)\n    }\n\n    // MARK: Part 4 - Largest drift magnitude in either direction\n\n    /// Calibration scoring cares how far a stretch pulled away from centre, not\n    /// which way. The most negative window is the most positive magnitude once\n    /// its sign is dropped, so the same two scans answer this too.\n    public func largestDriftMagnitude(deltas: [Int]) throws(DriftError) -> Int {\n        guard !deltas.isEmpty else { throw .emptySeries }\n        let largest = extremeWindow(deltas, maximising: true).total\n        let smallest = extremeWindow(deltas, maximising: false).total\n        return max(largest, -smallest)\n    }\n}\n"};
